import{_ as s,c as e,o as n,ag as t}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Self-Hosting Kasm","description":"","frontmatter":{"title":"Self-Hosting Kasm"},"headers":[],"relativePath":"general/self-hosting-kasm.md","filePath":"general/self-hosting-kasm.md","lastUpdated":null}'),l={name:"general/self-hosting-kasm.md"};function i(o,a,r,p,d,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="self-hosting-kasm" tabindex="-1">Self-Hosting Kasm <a class="header-anchor" href="#self-hosting-kasm" aria-label="Permalink to &quot;Self-Hosting Kasm&quot;">​</a></h1><h2 id="self-hosting-kasm-guide" tabindex="-1">Self-Hosting Kasm Guide <a class="header-anchor" href="#self-hosting-kasm-guide" aria-label="Permalink to &quot;Self-Hosting Kasm Guide&quot;">​</a></h2><p>This guide provides step-by-step instructions for self-hosting Kasm Workspaces, following the official Kasm documentation for a single server installation.</p><h3 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h3><p>Follow the steps below to install Kasm on your server.</p><h3 id="install-required-dependencies" tabindex="-1">Install Required Dependencies <a class="header-anchor" href="#install-required-dependencies" aria-label="Permalink to &quot;Install Required Dependencies&quot;">​</a></h3><p>Before installing Kasm, you need to install the required dependencies on your server:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Install requirements</span></span>
<span class="line"><span>apt install sudo -y</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install curl docker docker-compose -y</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="download-and-install-kasm" tabindex="-1">Download and Install Kasm <a class="header-anchor" href="#download-and-install-kasm" aria-label="Permalink to &quot;Download and Install Kasm&quot;">​</a></h3><p>After installing the necessary dependencies, move to the <code>/tmp</code> directory and download Kasm:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Move to tmp and download Kasm</span></span>
<span class="line"><span>cd /tmp</span></span>
<span class="line"><span>curl -O https://kasm-static-content.s3.amazonaws.com/kasm_release_1.14.0.3a7abb.tar.gz</span></span>
<span class="line"><span>tar -xf kasm_release_1.14.0.3a7abb.tar.gz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Next, run the installation script with the appropriate options:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Run the installation script</span></span>
<span class="line"><span>sudo bash kasm_release/install.sh --accept-eula --swap-size 8192</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If the installation fails, try running the command again.</p><h3 id="post-installation" tabindex="-1">Post Installation <a class="header-anchor" href="#post-installation" aria-label="Permalink to &quot;Post Installation&quot;">​</a></h3><p>After installation, you can access Kasm by navigating to your server&#39;s IP address in your web browser. Follow the prompts to finish the setup.</p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><p>If you encounter issues during the installation, ensure that all dependencies are correctly installed, and check the <a href="https://www.kasmweb.com/docs/latest/install/single_server_install.html" target="_blank" rel="noreferrer">Documentation</a> for additional support.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><ul><li>[*</li><li></li></ul>`,20)])])}const m=s(l,[["render",i]]);export{u as __pageData,m as default};
